from pathlib import Path
from html import escape
import json
from urllib.parse import quote

ROOT = Path(__file__).parent
DIST = ROOT / 'dist'
IG = 'https://www.instagram.com/bakedbyadeela/'
NAV = [('weddings.html','Weddings'),('bouquets.html','Cupcake bouquets'),('celebration-cakes.html','Celebration cakes'),('flavours.html','Flavours'),('about.html','My story'),('blog.html','Journal')]
arrow = '<svg class="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="M6 18 18 6M7 6h11v11"/></svg>'
def button(href,label,secondary=False):
    return f'<a class="button{" secondary" if secondary else ""}" href="{href}">{label}{arrow}</a>'
def link(href,label): return f'<a class="text-link" href="{href}">{label}{arrow}</a>'
def photo(name,alt,cls='',eager=False):
    sizes = {'adeela':(1660,2048),'wedding-bouquet':(1593,2048)}
    width,height=sizes.get(name,(1536,2048))
    return f'<figure class="{cls}"><img src="assets/{name}.jpg" alt="{escape(alt)}" width="{width}" height="{height}" {"fetchpriority=high" if eager else "loading=lazy"} decoding="async"></figure>'

def brand(header=False):
    if header: return '<a class="brand wordmark" href="index.html" aria-label="Baked By Adeela home"><span>BAKED</span><i>by</i><span>ADEELA</span></a>'
    return '<a class="brand" href="index.html" aria-label="Baked By Adeela home"><span class="brand-top">BAKED <i>by</i></span><span class="brand-name">Adeela</span></a>'
def cta(): return '<section class="cta blush center"><h2>A beautiful occasion.<br>A cake to <em>remember.</em></h2><p>Let’s bring your favourite flowers, flavours and colours together.</p>'+button('enquiry.html','Enquire about your occasion')+'</section>'
def intro(title,desc): return f'<div class="wrap page-intro"><h1>{title}</h1><p>{desc}</p></div>'
def enquiry(category='',design=''):
    return 'enquiry.html?collection='+quote(category)+'&design='+quote(design)

def gallery(items):
    return '<div class="product-gallery">'+''.join(f'<a class="product" href="{enquiry(cat,title)}">{photo(im,alt)}<span class="product-caption"><span>{title}</span><span class="product-action">Enquire {arrow}</span></span></a>' for im,title,cat,alt in items)+'</div>'

def instagram():
    items=[('blush-bouquet','Blush pink floral cupcake bouquet'),('cake','Lilac fairy garden celebration cake'),('wedding','Wedding cake with red floral details'),('wedding-bouquet','Adeela arranging a wedding cupcake bouquet')]
    return f'<section class="instagram-section"><div class="wrap"><div class="section-heading"><div><h2>A little more <em>flower magic.</em></h2><p>Explore the studio on Instagram, from buttercream details to finished celebrations.</p></div><a class="text-link" href="{IG}" target="_blank" rel="noopener noreferrer">@bakedbyadeela {arrow}</a></div><div class="instagram-grid" id="instagram-feed">'+''.join(f'<a href="{IG}" target="_blank" rel="noopener noreferrer" aria-label="{alt} — visit Baked By Adeela on Instagram">{photo(im,alt)}</a>' for im,alt in items)+'</div><p class="feed-note" id="feed-note">From the Baked By Adeela portfolio. See the latest posts on Instagram.</p></div></section>'

PAGES=[]
def page(filename,title,desc,body,noindex=False):
    PAGES.append(filename)
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==filename else '')+f'>{label}</a>' for url,label in NAV)
    canonical='https://bakedbyadeela.netlify.app/'+('' if filename=='index.html' else filename)
    structured={'@context':'https://schema.org','@type':'Bakery','@id':'https://bakedbyadeela.netlify.app/#business','name':'Baked By Adeela','url':'https://bakedbyadeela.netlify.app/','description':'Floral cupcake bouquets, wedding and celebration cakes with hand-piped buttercream flowers in Birmingham and the Midlands.','image':'https://bakedbyadeela.netlify.app/assets/bouquet.jpg','areaServed':['Birmingham','West Midlands','Midlands'],'sameAs':[IG]}
    robots='<meta name="robots" content="noindex,follow">' if noindex else '<meta name="robots" content="index,follow">'
    html=f'''<!doctype html>
<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Baked By Adeela</title><meta name="description" content="{escape(desc)}">{robots}<link rel="canonical" href="{canonical}"><meta name="theme-color" content="#e9d4d5"><meta property="og:title" content="{escape(title)} | Baked By Adeela"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://bakedbyadeela.netlify.app/assets/bouquet.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="style.css"><script src="app.js" defer></script><script type="application/ld+json">{json.dumps(structured)}</script></head>
<body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="header-inner">{brand(True)}<button class="menu-toggle" aria-expanded="false" aria-controls="navigation" aria-label="Open navigation"><span>Menu</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="M3 7h18M3 12h18M3 17h18"/></svg></button><nav class="nav" id="navigation" aria-label="Main navigation">{nav}<a class="nav-contact" href="enquiry.html">Enquire {arrow}</a></nav></div></header>
<main id="main">{body}</main><footer class="footer"><div class="wrap"><div class="footer-grid"><div>{brand()}<p>Floral cupcake bouquets.<br>Wedding &amp; celebration cakes.<br>Birmingham &amp; the Midlands.</p><a class="text-link" href="{IG}" target="_blank" rel="noopener noreferrer">Instagram {arrow}</a></div><div><h2 class="footer-title">The collections</h2><div class="footer-links"><a href="bouquets.html">Floral cupcake bouquets</a><a href="celebration-cakes.html">Celebration cakes</a><a href="weddings.html">Wedding cakes &amp; bouquets</a><a href="flavours.html">Flavour menu</a></div></div><div><h2 class="footer-title">A little more</h2><div class="footer-links"><a href="about.html">Meet Adeela</a><a href="how-it-works.html">How it works</a><a href="blog.html">The journal</a><a href="contact.html">Contact</a><a href="enquiry.html">Make an enquiry</a><a href="privacy.html">Privacy</a></div></div></div><div class="footer-bottom"><span>© 2026 Baked By Adeela</span><span>Flowers in buttercream. Made for your moment.</span></div></div></footer></body></html>'''
    (DIST/filename).write_text(html,encoding='utf-8')

collections=[('wedding','weddings.html','Wedding cakes & bouquets','Romantic little blooms for your biggest day. A beautiful detail, made to be shared.'),('bouquet','bouquets.html','Cupcake bouquets','A bouquet with a delicious secret. Delicate buttercream flowers for someone special.'),('cake','celebration-cakes.html','Celebration cakes','A centrepiece for the moments that deserve a little more magic.')]
cards=''.join(f'<article class="collection"><a href="{url}">{photo(im,title)}<h3>{title}</h3></a><p>{copy}</p>{link(url,"Explore the collection")}</article>' for im,url,title,copy in collections)
steps='<div class="journey"><article><h3>Share your occasion</h3><p>A birthday, a wedding, or a just-because gift. Tell me the date, your ideas, and who we’re celebrating.</p></article><article><h3>Make it your own</h3><p>We’ll discuss colours, flavours and all the little details, then confirm a design and quote together.</p></article><article><h3>Celebrate beautifully</h3><p>Once the details and arrangements are agreed, all that’s left is to look forward to your celebration.</p></article></div>'
page('index.html','Floral Cupcake Bouquets & Cakes in Birmingham','Discover floral cupcake bouquets, wedding and celebration cakes in Birmingham and the Midlands, finished with hand-piped buttercream flowers.',f'''<section class="hero-gallery" aria-label="Floral cakes and cupcake bouquets by Adeela"><a href="bouquets.html" aria-label="Explore floral cupcake bouquets">{photo('bouquet','Lilac and pink hand-piped buttercream cupcake bouquet','',True)}<span>Cupcake bouquets {arrow}</span></a><a href="weddings.html" aria-label="Explore wedding cakes and bouquets">{photo('wedding','Two-tier floral wedding cake surrounded by red and ivory cupcake bouquets','',True)}<span>Weddings {arrow}</span></a><a href="celebration-cakes.html" aria-label="Explore celebration cakes">{photo('cake','Lilac fairy garden celebration cake with buttercream roses','',True)}<span>Celebration cakes {arrow}</span></a></section><section class="home-intro wrap center"><h1>Beautiful flowers.<br><em>Even more beautiful in buttercream.</em></h1><p>Floral cupcake bouquets, wedding and celebration cakes,<br class="desktop-break"> lovingly created in Birmingham for occasions across the Midlands.</p><p class="intro-detail">A rose, a ruffle, a tiny petal. Every hand-piped buttercream flower brings a little of nature’s beauty to something delicious. From a thoughtful gift to a wedding centrepiece, let’s create a cake that feels like you.</p>{button('enquiry.html','Let’s create something beautiful')}</section><section class="section sage" id="collections"><div class="wrap"><div class="section-heading"><h2>For all of life’s<br><em>lovely occasions.</em></h2><p>A beautiful starting point for your celebration. Explore the collection, then tell me what you have in mind.</p></div><div class="collections">{cards}</div></div></section><section class="section"><div class="wrap split maker">{photo('adeela','Adeela adding hand-piped buttercream flowers to a wedding cupcake bouquet')}<div class="split-copy"><h2>Hello, I’m <em>Adeela.</em></h2><p>I create floral cakes and cupcake bouquets in Birmingham, bringing a love of flowers to the celebrations that matter to you.</p><p>For me, it’s the little details that make something personal: a favourite flower, a soft colour palette, or a meaningful occasion. Each buttercream bloom is piped by hand and brought together in a design made for your moment.</p><p>Whether you’re choosing a thoughtful gift or planning a wedding in the Midlands, I’d love to hear your ideas.</p>{link('about.html','A little about me')}</div></div></section><section class="section lilac"><div class="wrap center"><h2>From your first idea<br>to the <em>final flower.</em></h2>{steps}{link('how-it-works.html','Discover the journey')}</div></section>{instagram()}{cta()}''')

page('about.html','Meet Adeela — Floral Cake Maker in Birmingham','Meet Adeela, the maker behind floral cupcake bouquets and hand-piped buttercream celebration cakes in Birmingham and the Midlands.',intro('A love of flowers.<br>A little <em>buttercream magic.</em>','Meet the hands and heart behind Baked By Adeela.')+f'''<section class="section"><div class="wrap split maker">{photo('adeela','Adeela decorating a large floral cupcake bouquet at a wedding')}<div class="split-copy"><h2>Hello, I’m <em>Adeela.</em></h2><p>Welcome to Baked By Adeela. I create floral cupcake bouquets, wedding and celebration cakes in Birmingham, inspired by the colours and delicate details of flowers.</p><p>Hand-piped buttercream flowers are at the heart of my work. From soft pink roses and lilac petals to a fuller, statement bouquet, each design brings together the beauty of a floral arrangement and the joy of sharing cake.</p><p>I love how personal a cake can be. A favourite colour, a flower that means something, a thoughtful gift for someone special — these little details are where your design begins.</p><p>If you’re celebrating in Birmingham or the Midlands, tell me about your occasion. Together we can explore the colours, flavours and finishing touches that make it yours.</p><div class="signature">With love, Adeela</div>{button('enquiry.html','Tell me about your occasion')}</div></div></section><section class="section sage"><div class="wrap center"><h2>Flowers you can admire.<br>Cake you can <em>share.</em></h2><p>Explore hand-piped floral cupcakes, meaningful gifts and beautiful celebration centrepieces.</p>{link('bouquets.html','Explore cupcake bouquets')}</div></section>'''+instagram())

faqs=[('How do I make an enquiry?','Choose a design or use any enquiry button to open the shared enquiry form. Please include your date and the kind of creation you have in mind.'),('How much notice should I give?','Enquire as soon as you have a celebration date. Availability and the time needed for your design will be confirmed directly before an order is agreed.'),('Can I choose my colours and flowers?','Share your palette, favourite flowers or inspiration with your enquiry. The final design and what is achievable will be discussed with you.'),('How much will my order cost?','A personalised quote can be confirmed after the size, design and other details are discussed. Every quote reflects the size and detail of your design.'),('Can you accommodate dietary requirements?','Mention any allergies or dietary needs before ordering. Ingredients, cross-contact risks and suitability must be confirmed directly; this website does not promise allergen-free products.'),('Is collection or delivery available?','Ask about collection or delivery when enquiring. The location, timing, any delivery charge and safe transport arrangements need to be confirmed with Adeela.')]
page('how-it-works.html','How it works','Your journey from a first idea to a beautiful cake or cupcake bouquet.',intro('Your idea.<br>Our <em>lovely journey.</em>','A few thoughtful steps from “I have an idea” to a celebration that feels beautifully yours.')+f'<section class="section"><div class="wrap">{steps}<div class="notice">Your date, design, price and fulfilment arrangements are confirmed directly. An enquiry does not reserve a date or place an order.</div></div></section><section class="section sage" id="questions"><div class="wrap"><h2 class="center">A few things you<br>might be <em>wondering.</em></h2><div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faqs)+'</div></div></section>'+cta())

flavours=[('Vanilla bean','classic','#eadbc0','A delicate vanilla sponge with silky vanilla buttercream. Simple, soft and endlessly lovely.'),('Chocolate velvet','classic','#9b7662','Rich chocolate sponge paired with smooth chocolate buttercream. A little indulgence in every bite.'),('Lemon & elderflower','fruit','#e6d596','Bright lemon sponge with a delicate elderflower-inspired finish. Light and beautifully fragrant.'),('Raspberry & white chocolate','fruit','#d9aeb2','A gentle balance of tart raspberry and creamy white chocolate sweetness.'),('Rose & pistachio','signature','#bcc5a9','Soft floral notes and the mellow, nutty character of pistachio. A romantic pairing.'),('Salted caramel','signature','#cfa773','Warm caramel sweetness with a subtle salty finish. Comforting, rich and celebratory.')]
flavour_html=''.join(f'<article class="flavour" data-category="{cat}"><span class="dot" style="background:{colour}" aria-hidden="true"></span><div><h3>{name}</h3><p>{desc}</p></div></article>' for name,cat,colour,desc in flavours)
page('flavours.html','Flavour menu','Explore a draft selection of flavour ideas for cakes and cupcake bouquets.',intro('As delicious<br>as they are <em>beautiful.</em>','A little inspiration for what’s inside. Discover classic favourites, fruity pairings and something a little unexpected.')+f'<section class="section" style="padding-top:20px"><div class="wrap"><div class="filter-bar" aria-label="Filter flavour ideas">'+''.join(f'<button class="filter" data-filter="{key}" aria-pressed="{str(key=="all").lower()}">{label}</button>' for key,label in [('all','All flavours'),('classic','The classics'),('fruit','Fresh & fruity'),('signature','Something special')])+f'</div><p id="filter-status" class="center note" role="status">6 flavour ideas shown</p><div class="flavours">{flavour_html}</div><div class="notice"><strong>Sample flavour menu.</strong> These pairings are draft ideas, not a confirmed product list. Please ask Adeela about current flavours, ingredients and dietary requirements before ordering.</div></div></section>'+cta())

details=[('bouquets.html','Cupcake bouquets','A bouquet.<br>A sweet <em>surprise.</em>','bouquet','Floral cupcake bouquets in Birmingham, with hand-piped buttercream roses and delicate blooms. A thoughtful gift for birthdays, anniversaries and celebrations across the Midlands.','Cupcake bouquets','Think birthdays, thank-yous, anniversaries — or a lovely surprise just because. Share a favourite colour and the feeling you have in mind.','A palette to fall for','Blush pink, soft lilac, ivory and a touch of sage. Your palette is a starting point for a design that feels personal.'),('celebration-cakes.html','Celebration cakes','The sweetest<br><em>centrepiece.</em>','cake','Bespoke celebration cakes in Birmingham, decorated with hand-piped buttercream flowers. From fairy garden birthdays to milestone occasions, a beautiful centrepiece made around your celebration.','Celebration cakes','From a quiet birthday gathering to a milestone worth celebrating, tell me your guest count, colour palette and any meaningful details.','Made around your moment','Romantic florals, delicate colour and considered details. Together we can explore the right direction for your celebration.'),('weddings.html','Wedding cakes & bouquets','For your<br><em>forever moment.</em>','wedding','Floral wedding cakes and cupcake bouquets for celebrations in Birmingham and the Midlands. Hand-piped buttercream flowers, romantic colours and a centrepiece made for your day.','Wedding cupcake bouquets','Share your wedding date, venue, guest numbers and palette. Whether you imagine ivory blooms or soft touches of colour, we’ll start with your vision.','Beautifully in harmony','Consider the flowers, stationery and textures of your day. A coordinated palette can make your cupcake bouquets feel naturally part of the celebration.')]
for filename,title,heading,im,desc,category,copy,sub,subcopy in details:
    href=enquiry(category)
    items = {'bouquet':[('bouquet','Lilac garden bouquet',category,'Lilac and pink floral cupcake bouquet'),('blush-bouquet','Blush & berry bouquet',category,'Pink and plum hand-piped buttercream flowers')], 'cake':[('cake','Fairy garden cake',category,'Lilac fairy garden birthday cake with buttercream roses')], 'wedding':[('wedding','Floral wedding cake','Wedding cake','Two-tier wedding cake with red floral decoration'),('wedding-bouquet','Wedding cupcake centrepiece',category,'Adeela arranging a large wedding cupcake bouquet')] }[im]
    product_section='<section class="section"><div class="wrap"><div class="section-heading"><h2>A little <em>inspiration.</em></h2><p>Choose a design to begin your enquiry. Colours, size and flowers can be discussed together.</p></div>'+gallery(items)+'</div></section>'
    page(filename,title,desc,f'<div class="wrap"><div class="breadcrumb"><a href="index.html#collections">The collections</a> / {title}</div><section class="detail-hero split">{photo(im,title.lower()+" with hand-piped buttercream flowers by Adeela",eager=True)}<div class="split-copy"><h1>{heading}</h1><p>{desc}</p><p>{copy}</p>{button(href,"Enquire about this collection")}<p class="note">Designed around your occasion. Final design, size, price and availability confirmed on enquiry.</p></div></section></div><section class="section {"lilac" if im=="cake" else "sage"}"><div class="wrap split"><div><h2>{sub}</h2><p>{subcopy}</p><div class="palette" aria-label="Blush, lilac, sage and ivory colour inspiration"><span class="swatch" style="background:#e6c4c5" title="Blush"></span><span class="swatch" style="background:#d2c4de" title="Lilac"></span><span class="swatch" style="background:#b7c0a9" title="Sage"></span><span class="swatch" style="background:#faf5e9" title="Ivory"></span></div></div><div><h3>Beauty, inside and out.</h3><p>Browse the flavour ideas, then tell me what you love. Your creation should feel just as special in its flavour as it does in its design.</p>{link("flavours.html","Explore the flavour menu")}</div></div></section>'+product_section+cta())

page('contact.html','Contact Baked By Adeela — Birmingham & Midlands','Contact Adeela about floral cupcake bouquets, wedding cakes and celebration cakes in Birmingham and the Midlands.',intro('Let’s make something<br><em>beautiful together.</em>','Choose what you have in mind to open the enquiry form. Your idea doesn’t need to be fully formed.')+f'<section class="section"><div class="wrap">'+gallery([('bouquet','A floral cupcake bouquet','Cupcake bouquets','Pink and lilac floral cupcake bouquet'),('cake','A celebration cake','Celebration cakes','Lilac floral celebration cake'),('wedding','A wedding creation','Wedding cupcake bouquets','Floral wedding cake and cupcake bouquets')])+f'<div class="contact-note center"><h2>Just a little <em>question?</em></h2><p>You can also say hello on Instagram at <a class="text-link" href="{IG}">@bakedbyadeela</a>.</p><p>Based in Birmingham, for celebrations across the Midlands. Collection and delivery arrangements are confirmed with your enquiry.</p>{button("enquiry.html","Open the enquiry form")}</div></div></section>')

page('enquiry.html','Make an Enquiry — Cakes & Cupcake Bouquets','Tell Adeela about your cake or floral cupcake bouquet, occasion and date. Enquiries for Birmingham and the Midlands.',intro('Your occasion.<br>Your <em>beautiful details.</em>','A date, a favourite flower, a colour you love. Tell me a little about the celebration you have in mind.')+'''<section class="section form-section"><div class="wrap enquiry-layout"><aside><h2>Let’s bring your<br><em>ideas to life.</em></h2><p>Your selected collection and design will appear in the form. Feel free to change them if another idea takes your fancy.</p><p>Once your enquiry arrives, we can discuss availability, flavours, size and a personalised quote.</p><p class="note">An enquiry does not reserve a date or confirm an order. Please tell us about any dietary requirements before ordering.</p><a class="text-link" href="how-it-works.html">How it works</a></aside><div><form id="enquiry-form" name="cake-enquiry" method="POST" action="/thank-you.html" data-netlify="true" netlify-honeypot="bot-field"><input type="hidden" name="form-name" value="cake-enquiry"><p hidden><label>Leave this empty <input name="bot-field" tabindex="-1" autocomplete="off"></label></p><div class="form-grid"><div class="field"><label for="name">Your name *</label><input id="name" name="name" autocomplete="name" required maxlength="100"></div><div class="field"><label for="email">Email address *</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="150"></div><div class="field full"><label for="collection">What would you like? *</label><select id="collection" name="collection" required><option value="">Choose a collection</option><option>Cupcake bouquets</option><option>Celebration cakes</option><option>Wedding cake</option><option>Wedding cupcake bouquets</option><option>Something else</option></select></div><div class="field full"><label for="design">Design that caught your eye</label><input id="design" name="design" maxlength="150" placeholder="Optional — or tell me about your own idea"></div><div class="field"><label for="date">Celebration date *</label><input id="date" name="date" type="date" required></div><div class="field"><label for="guests">Guests / cupcakes</label><input id="guests" name="guests" type="number" min="1" max="10000" placeholder="Approximate number"></div><div class="field full"><label for="location">Celebration location / venue</label><input id="location" name="location" maxlength="200" autocomplete="address-level2" placeholder="Town, postcode or venue"></div><div class="field full"><label for="message">Tell me about your occasion *</label><textarea id="message" name="message" required minlength="10" maxlength="3000" placeholder="Your colours, favourite flowers, budget and anything else you would like me to know…"></textarea></div></div><p class="form-note">Your details are used to respond to your enquiry. Please read our <a href="privacy.html">privacy information</a>.</p><button class="button" type="submit">Send my enquiry <svg class="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="M6 18 18 6M7 6h11v11"/></svg></button><p id="form-status" role="status" class="form-status"></p><p class="note">Prefer a message? Find <a class="text-link" href="https://www.instagram.com/bakedbyadeela/">@bakedbyadeela on Instagram</a>.</p></form></div></div></section>''',noindex=True)
page('thank-you.html','Thank You for Your Enquiry','Your cake enquiry has been submitted.',intro('Thank you.<br>Let’s make something <em>lovely.</em>','Your enquiry has been submitted. Adeela will be in touch using the email address you provided.')+'<section class="section center">'+button('index.html','Back to the home page')+'</section>',noindex=True)
page('privacy.html','Enquiry Privacy','How the website handles your enquiry details.',intro('Your details,<br>handled with <em>care.</em>','Information about the enquiry form and Instagram gallery.')+'''<article class="article wrap"><h2>What you share</h2><p>The enquiry form asks for your name, email address and celebration details so Baked By Adeela can respond to your request. Please only include information you are comfortable sharing and avoid sensitive personal or health information. Dietary requirements can be discussed directly.</p><h2>How enquiries are handled</h2><p>Form submissions are processed and stored through Netlify Forms for Baked By Adeela to review and answer. Your details are used to discuss your enquiry and any resulting order, not to sign you up to marketing.</p><h2>Instagram and external links</h2><p>The website links to Instagram. When a live Instagram connection is enabled, the gallery may load images from Meta’s servers. These services receive normal connection information, such as your IP address, when their content loads. Instagram’s own privacy settings and policies apply when you visit it.</p><h2>Questions about your information</h2><p>Contact Baked By Adeela through <a class="text-link" href="https://www.instagram.com/bakedbyadeela/">@bakedbyadeela on Instagram</a> to ask about your enquiry information or request its deletion.</p></article>''',noindex=True)

posts=[('choosing-your-palette.html','A palette for your perfect occasion','bouquet','Colour inspiration','Start with a feeling, choose a favourite shade, and let the little details fall into place.'),('a-bouquet-with-a-difference.html','A bouquet with a delicious difference','wedding','Thoughtful gifting','Flowers or cake? A cupcake bouquet brings both ideas together in one lovely gesture.'),('planning-your-celebration.html','The little guide to a lovely cake enquiry','cake','Celebration notes','A few helpful details to have in mind when you begin planning your celebration cake.')]
page('blog.html','The journal','Colour inspiration, thoughtful gifting and celebration ideas from Baked by Adeela.',intro('Notes from<br>the <em>cake studio.</em>','A little inspiration, a few thoughtful details, and ideas for your next lovely celebration.')+'<section class="section"><div class="wrap journal">'+''.join(f'<article><a href="{url}">{photo(im,title)}<h2>{title}</h2><p class="meta">{cat} · 3 minute read</p></a><p>{copy}</p>{link(url,"Read the story")}</article>' for url,title,im,cat,copy in posts)+'</div></section>'+cta())
articles=[('''<h2>Begin with a feeling</h2><p>Before choosing individual colours, think about the mood of the occasion. Is it quiet and romantic, fresh and joyful, or soft and understated? A clear feeling makes the smaller decisions easier.</p><h2>Choose one colour to lead</h2><p>Blush pink makes a beautiful starting point for a romantic palette. Lilac brings a gentle, playful character, while ivory feels quietly timeless. Pick one shade you love, then let the others support it.</p><h2>Let greenery give the colours space</h2><p>A touch of sage can soften a pink and lilac combination. Think of it as breathing room between the blooms: it gives the floral shapes definition without competing for attention.</p><h2>Bring your inspiration</h2><p>A ribbon, an invitation, or a photograph of your flowers can communicate a palette more clearly than a colour name alone. Share these details when enquiring, and remember that colours look different on screens and in different light.</p>'''),('''<h2>A familiar gesture, reimagined</h2><p>A bunch of flowers is a wonderful way to say thank you. A cake invites people to pause and share something sweet. A cupcake bouquet combines the spirit of both: a floral arrangement with a delicious surprise.</p><h2>Make the thought personal</h2><p>Consider the recipient’s favourite colours, the reason for the gift, and how many people might share it. A soft ivory palette feels very different from a bouquet full of blush and lilac — neither needs to be complicated to feel special.</p><h2>Think about the moment it arrives</h2><p>Will it be presented at a party, taken to a dinner, or given as a quiet surprise? Mention your plans when enquiring so that packaging, timing and handling can be discussed.</p><h2>Ask before ordering</h2><p>Check flavours, ingredients and dietary needs directly before confirming. Share the celebration date and ask about availability and collection or delivery arrangements.</p>'''),('''<h2>Start with the date</h2><p>Your celebration date is the most useful place to begin. Include it in your first message, even if you have not decided on a design. Availability needs to be confirmed before the finer details are agreed.</p><h2>Have a rough guest count</h2><p>Knowing how many people you expect to serve helps shape the conversation about cake size or cupcake quantities. An estimate is a helpful starting point; the final serving requirements can be discussed together.</p><h2>Share what you love</h2><p>You do not need a complete design. A colour palette, a favourite flower, or a few inspiration images can be enough to explain your direction. Include any words, names or details that matter to your celebration.</p><h2>Include the practical details</h2><ul><li>The date and type of occasion.</li><li>Your estimated guest count and budget.</li><li>Your preferred colours and flavours.</li><li>Any allergies or dietary requirements.</li><li>Your collection or delivery needs.</li></ul><p>The enquiry form brings these details together and sends them to Adeela. An enquiry begins the conversation; it does not confirm a booking.</p>''')]
for (url,title,im,cat,copy),text in zip(posts,articles):
    page(url,title,copy,intro(title,cat+' · Studio journal')+f'<article class="article wrap"><img src="assets/{im}.jpg" alt="Floral cake and cupcake design by Baked By Adeela" width="1122" height="1402">{text}{link("enquiry.html","Start your enquiry")}<br>{link("blog.html","Back to the journal")}</article>')

